class Solution {
  public long rob(int[] nums, int[] colors) {
    long skip = 0, take = 0;
    for (int i = 0; i < nums.length; i++) {
      long newSkip = Math.max(skip, take);
      long newTake = (i > 0 && colors[i] == colors[i - 1] ? skip : Math.max(skip, take)) + nums[i];
      skip = newSkip;
      take = newTake;
    }
    return Math.max(skip, take);
  }
}
